async commitOrder(order: OrderDraft): Promise<void> {
  if (order.customerId.trim().length === 0) {
    promptAction.showToast({ message: 'Required customer' })
    return
  }
  this.dispatchCommit(order)
  await this.orderStore.save(order)
}

private async commitSelectedLedgerBatch(): Promise<void> {
  if (this.pendingCount === 0) {
    return
  }
  await LedgerStore.validatePendingBatch()
  await LedgerStore.commitPendingBatch()
  this.pendingCount = 0
  this.statusText = 'ledger batch committed'
}

